toolCalls.input:
{"command": "cd $TMPDIR && d=$(mktemp -d) && cat > "$d/notes" <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
file="${NOTES_FILE:-$HOME/.notes}"
case "${1:-}" in
  add) shift; printf '%s\n' "$*" >> "$file" ;;
  list) [ -f "$file" ] && cat "$file" || true ;;
  search)
    [ $# -eq 2 ] && [ -n "$2" ] || { echo "usage: notes add <text> | notes list | notes search <word>" >&2;
